excels.excel:

EXPORT WITH SHEET="客户投诉处理台账", HEADER=true,
    MAPPING={"a":"投诉单号","b":"客户","c":"投诉类型","d":"受理日期","e":"处理时限(天)","f":"实际处理天数","g":"是否超期"},
    FORMAT={"d":"yyyy-MM-dd","e":"0","f":"0.0"},
    FORMULAS={
        F8:'AVERAGE(F2:F7)'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true},
        F7:{color:red,bold:true}
    }
